import requests

def fetch_user_profile(session_token, user_id, include_history=False):
    """Fetch a user's profile from the account service."""
    headers = {"Authorization": f"Bearer {session_token}", "Accept": "application/json"}
    params = {"id": user_id}
    if include_history:
        params["history"] = "true"
    response = requests.get("https://api.example.com/v2/users/profile", headers=headers, params=params)
    if response.status_code == 404:
        return None
    response.raise_for_status()
    data = response.json()
    profile = {
        "id": data["id"],
        "name": data.get("display_name") or data.get("username"),
        "email": data.get("email"),
        "created": data.get("created_at"),
        "plan": data.get("subscription", {}).get("plan", "free"),
    }
    if include_history:
        profile["history"] = [event["type"] for event in data.get("events", [])]
    return profile
